var a=`1330-causa-limena`;var t=`world-1330`;var n=`PE`;var o=`south-america`;var r=4;var s=135;var l={en:`Causa Limeña`,ua:`Кауса ліменья`};var m={en:`Causa Limeña is a dish from Peru featuring potato, aji amarillo paste, lime juice, chicken breast. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Кауса ліменья, страва кухні країни Перу з такими основними складниками: картопля, паста ахі амарильйо, сік лайма, куряча грудка. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Cook the listed ingredients in simmering water for about 27 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 27 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:27,i:[[`potato`,760,`g`],[`water`,1e3,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[[`aji-amarillo-paste`,45,`g`],[`lime-juice`,70,`ml`],[`canola-oil`,75,`ml`]]},{en:`Poach the listed ingredients in barely simmering liquid for about 18 minutes until tender and cooked through.`,ua:`Пошируйте зазначені продукти в рідині без бурхливого кипіння приблизно 18 хвилин до готовності й м’якості.`,t:[`poaching`],m:18,i:[[`chicken-breast`,420,`g`],[`water`,500,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:9,i:[[`mayonnaise`,120,`g`],[`avocado`,2,`pcs`]]},{en:`Layer the previously prepared components evenly inside a baking dish, serving mold or plate appropriate to the recipe; smooth the surface and avoid mixing the layers.`,ua:`Рівномірно викладіть підготовлені компоненти шарами у формі для запікання, подавання чи на тарілці відповідно до страви; вирівняйте поверхню, не змішуючи шари.`,t:[`layered-assembly`],m:13,i:[]},{en:`Refrigerate the prepared mixture for about 60 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 60 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:60,i:[]}];var u={slug:a,id:t,country:`PE`,region:o,servings:4,minutes:135,title:l,text:m,steps:d};export{n as country,u as default,t as id,s as minutes,o as region,r as servings,a as slug,d as steps,m as text,l as title};